//! Native Checker text transport DATA; no source/model/completion authority.
use crate::selected_exclusions_wire::{Hex128,Seal,MAX_STREAM};use serde::{Deserialize,Serialize};use std::{io,path::{Path,PathBuf}};
#[derive(Clone,Copy,Debug,Serialize,Deserialize,Eq,PartialEq)]pub enum Schema{#[serde(rename="native-checker-text-v1")]V1}
#[derive(Clone,Copy,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Frame{pub semantic_revision:Hex128,pub source_revision:Hex128,pub policy_revision:Hex128}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Terminal{pub schema:Schema,pub complete:bool,pub full_checker_parity:bool,pub project:PathBuf,pub emitted:u64,pub visited_bodies:u64,pub exit_code:u8,pub frame:Frame,#[serde(deserialize_with="present_diagnostics")]pub diagnostics:Option<Seal>,pub output:Seal}
fn present_diagnostics<'de,D:serde::Deserializer<'de>>(d:D)->Result<Option<Seal>,D::Error>{Option::<Seal>::deserialize(d)}
impl Terminal{pub fn require(&self,project:&Path)->io::Result<()>{
 let bad=||io::Error::new(io::ErrorKind::InvalidData,"Checker terminal differs from the requested completed text operation");
 if !self.complete||self.full_checker_parity||self.project!=project||!self.project.is_absolute()||self.exit_code!=u8::from(self.emitted!=0)||self.output.length==0||self.output.length>MAX_STREAM||(self.emitted==0)!=self.diagnostics.is_none()||self.diagnostics.as_ref().is_some_and(|s|s.length==0||s.length>MAX_STREAM)||self.output.length.checked_add(self.diagnostics.as_ref().map_or(0,|s|s.length)).is_none_or(|n|n>MAX_STREAM){return Err(bad())}Ok(())
}}
#[cfg(test)]mod tests{use super::*;#[test]fn checker_terminal_denies_unfinished_foreign_false_parity_and_unsealed_diagnostics(){let project=PathBuf::from(if cfg!(windows){"E:/actual/project.dme"}else{"/actual/project.dme"});let mut t=Terminal{schema:Schema::V1,complete:true,full_checker_parity:false,project:project.clone(),emitted:0,visited_bodies:0,exit_code:0,frame:Frame{semantic_revision:Hex128(1),source_revision:Hex128(2),policy_revision:Hex128(3)},diagnostics:None,output:Seal{length:1,hash:Hex128(4)}};t.require(&project).unwrap();t.complete=false;assert!(t.require(&project).is_err());t.complete=true;t.full_checker_parity=true;assert!(t.require(&project).is_err());t.full_checker_parity=false;t.exit_code=1;assert!(t.require(&project).is_err());t.exit_code=0;let mut value=serde_json::to_value(&t).unwrap();value.as_object_mut().unwrap().remove("diagnostics");assert!(serde_json::from_value::<Terminal>(value).is_err());t.project=PathBuf::from("foreign");assert!(t.require(&project).is_err());}}
